import { Textarea } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof Textarea>,
    'label' | 'placeholder' | 'block' | 'rows'
  > = {
    label: 'Role description',
